fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left: usize = 0;
    let mut right: usize = v.len() - 1;

    // Loop invariant:
    // - v[left..=right] contains at least one occurrence of k
    // - left <= right < v.len()
    // - The search interval shrinks each iteration

    while left < right {
        let mid = left + (right - left) / 2;

        if v[mid] < k {
            // Since v[mid] < k, the target must be in v[mid+1..=right]
            left = mid + 1;
        } else {
            // If v[mid] >= k, target must be in v[left..=mid]
            // Because k is guaranteed to exist, and array is non-decreasing
            right = mid;
        }
    }
    // After loop, left == right and v[left] == k (since guaranteed in input)

    left
}